import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { doctorApi } from '../../api/doctorApi';
import Card from '../../components/Card';
import Loader from '../../components/Loader';
import ErrorBox from '../../components/ErrorBox';

const DoctorDashboard = () => {
  const navigate = useNavigate();
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const fetchAppointments = async () => {
    try {
      // Get all appointments, not just CONFIRMED
      const response = await doctorApi.getAppointments();
      if (response.success) {
        // Sort appointments by date (newest first) and then by time
        const sorted = response.appointments.sort((a, b) => {
          const dateA = new Date(a.appointmentDate);
          const dateB = new Date(b.appointmentDate);
          if (dateA.getTime() !== dateB.getTime()) {
            return dateB.getTime() - dateA.getTime(); // Newest first
          }
          // If same date, sort by time
          return (a.slotTime?.startTime || '').localeCompare(b.slotTime?.startTime || '');
        });
        setAppointments(sorted);
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to fetch appointments');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAppointments();
    // Refresh appointments every 30 seconds to see new bookings
    const interval = setInterval(fetchAppointments, 30000);
    return () => clearInterval(interval);
  }, []);

  if (loading) return <Loader />;

  const confirmedCount = appointments.filter(a => a.status === 'CONFIRMED' || a.status === 'PENDING').length;
  const completedCount = appointments.filter(a => a.status === 'COMPLETED').length;

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-4xl font-bold text-gray-900 mb-2">Doctor Dashboard</h1>
          <p className="text-gray-600">Manage your appointments and patient care.</p>
        </div>
        <button
          onClick={fetchAppointments}
          className="bg-blue-600 text-white px-6 py-3 rounded-xl hover:bg-blue-700 shadow-lg hover:shadow-xl transition-all duration-300 flex items-center space-x-2 font-medium"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
          </svg>
          <span>Refresh</span>
        </button>
      </div>
      {error && <ErrorBox message={error} onClose={() => setError('')} />}

      {/* Statistics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-blue-50 to-blue-100 border-blue-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-blue-600 text-sm font-medium mb-1">Total Appointments</p>
              <p className="text-4xl font-bold text-blue-900">{appointments.length}</p>
            </div>
            <div className="w-16 h-16 bg-blue-200 rounded-xl flex items-center justify-center">
              <svg className="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
          </div>
        </Card>
        <Card className="bg-gradient-to-br from-yellow-50 to-yellow-100 border-yellow-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-yellow-600 text-sm font-medium mb-1">Pending/Confirmed</p>
              <p className="text-4xl font-bold text-yellow-900">{confirmedCount}</p>
            </div>
            <div className="w-16 h-16 bg-yellow-200 rounded-xl flex items-center justify-center">
              <svg className="w-8 h-8 text-yellow-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
          </div>
        </Card>
        <Card className="bg-gradient-to-br from-green-50 to-green-100 border-green-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-green-600 text-sm font-medium mb-1">Completed</p>
              <p className="text-4xl font-bold text-green-900">{completedCount}</p>
            </div>
            <div className="w-16 h-16 bg-green-200 rounded-xl flex items-center justify-center">
              <svg className="w-8 h-8 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
          </div>
        </Card>
      </div>

      <div className="mb-6">
        <h2 className="text-2xl font-bold text-gray-900 mb-6">
          All Appointments ({appointments.length})
        </h2>
        {appointments.length > 0 ? (
          <div className="space-y-4">
            {appointments.map((appointment) => (
              <Card 
                key={appointment._id}
                className={appointment.status === 'CONFIRMED' || appointment.status === 'PENDING' 
                  ? 'border-l-4 border-l-blue-500' 
                  : appointment.status === 'COMPLETED' 
                  ? 'border-l-4 border-l-green-500' 
                  : ''}
              >
                <div className="flex justify-between items-start">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-2">
                      <h3 className="text-lg font-semibold">
                        {appointment.patient?.user?.name || 'N/A'}
                      </h3>
                      <span className={`px-2 py-1 text-xs font-semibold rounded ${
                        appointment.status === 'COMPLETED' ? 'bg-green-100 text-green-700' :
                        appointment.status === 'CONFIRMED' ? 'bg-blue-100 text-blue-700' :
                        appointment.status === 'PENDING' ? 'bg-yellow-100 text-yellow-700' :
                        'bg-red-100 text-red-700'
                      }`}>
                        {appointment.status}
                      </span>
                    </div>
                    <p className="text-gray-600 mb-1">
                      <strong>📅 Date:</strong> {new Date(appointment.appointmentDate).toLocaleDateString('en-US', { 
                        weekday: 'short', 
                        year: 'numeric', 
                        month: 'short', 
                        day: 'numeric' 
                      })}
                    </p>
                    <p className="text-gray-600 mb-1">
                      <strong>🕐 Time:</strong> {appointment.slotTime?.startTime} - {appointment.slotTime?.endTime}
                    </p>
                    <p className="text-gray-600 mb-1">
                      <strong>📋 Reason:</strong> {appointment.reason}
                    </p>
                    <p className="text-gray-600 mb-1">
                      <strong>📞 Phone:</strong> {appointment.patient?.user?.phone || 'N/A'}
                    </p>
                    {appointment.status === 'CONFIRMED' || appointment.status === 'PENDING' ? (
                      <p className="text-blue-600 text-sm font-semibold mt-2">
                        ✓ Ready to create prescription
                      </p>
                    ) : appointment.status === 'COMPLETED' ? (
                      <p className="text-green-600 text-sm font-semibold mt-2">
                        ✓ Prescription sent
                      </p>
                    ) : null}
                  </div>
                  <div className="ml-4">
                    <button
                      onClick={() => navigate(`/doctor/appointment/${appointment._id}`)}
                      className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 whitespace-nowrap"
                    >
                      View Details
                    </button>
                  </div>
                </div>
              </Card>
            ))}
          </div>
        ) : (
          <Card>
            <p className="text-center text-gray-600">No appointments found</p>
          </Card>
        )}
      </div>
    </div>
  );
};

export default DoctorDashboard;
